ALTER TABLE coleta_roupa_suja ADD COLUMN cancelado_em DATETIME(3) NULL, ADD COLUMN motivo_cancelamento VARCHAR(500) NULL, ADD CONSTRAINT ck_coleta_roupa_suja_cancelamento CHECK (situacao <> 'cancelada' OR motivo_cancelamento IS NOT NULL);
ALTER TABLE distribuicao_enxoval ADD COLUMN cancelado_em DATETIME(3) NULL, ADD COLUMN motivo_cancelamento VARCHAR(500) NULL, ADD CONSTRAINT ck_distribuicao_enxoval_cancelamento CHECK (situacao <> 'cancelada' OR motivo_cancelamento IS NOT NULL);
ALTER TABLE baixa_enxoval ADD COLUMN cancelado_em DATETIME(3) NULL, ADD COLUMN motivo_cancelamento VARCHAR(500) NULL, ADD CONSTRAINT ck_baixa_enxoval_cancelamento CHECK (situacao <> 'cancelada' OR motivo_cancelamento IS NOT NULL);
ALTER TABLE retorno_lavanderia DROP INDEX uq_retorno_lavanderia_remessa, ADD COLUMN remessa_vigente_id BIGINT UNSIGNED AS (IF(situacao = 'cancelado' OR excluido_em IS NOT NULL, NULL, remessa_lavanderia_id)) PERSISTENT COMMENT 'Um retorno vigente por remessa', ADD UNIQUE KEY uq_retorno_lavanderia_remessa_vigente (remessa_vigente_id), ADD KEY ix_retorno_lavanderia_remessa (remessa_lavanderia_id);
